from pathlib import Path
import re
ROOT=Path('app')

def read(rel): return (ROOT/rel).read_text(encoding='utf-8')
def write(rel,s): (ROOT/rel).write_text(s,encoding='utf-8')

# perks.ts
p='src/game/perks.ts'; s=read(p)
s=s.replace('  perk: Perk;\n}', '  perk: Perk;\n  /** False for rare-order members earned only through Special Missions. */\n  scoutable?: boolean;\n}',1)
anchor='''  sage: {\n    id: "sage", title: "Sage Aspirant", epithet: "of the Mountain", color: "#f4c64f",\n    blurb: "Draws chakra from the world itself. Calm, immovable, endlessly deep.",\n    bonus: { nin: 6, tai: 5, med: 5 }, pot: 5,\n    perk: mk("lg_sagemode", "Sage Mode", "仙", "#f4c64f",\n      "Unlocks 奥義 Sage Art. All combat stats +20% and chakra regenerates rapidly.",\n      { special: true, atk: 1.2, def: 1.2, hp: 1.2, regen: 5 },\n      { name: "Sage Art: Rasengan", power: 1.25, stat: "nin", hits: 1, note: "natural energy detonation" }),\n  },\n'''
if anchor not in s: raise SystemExit('sage anchor missing')
orders='''  beast_sage: {\n    id: "beast_sage", title: "Beast Sage", epithet: "of the Five Paths", color: "#79cf69", scoutable: false,\n    blurb: "One of the Five Beast Sages. Their animal covenant turns natural energy into relentless recovery and crushing summons.",\n    bonus: { nin: 7, tai: 5, med: 4, tac: 3 }, pot: 5,\n    perk: mk("lg_primalcovenant", "Primal Covenant", "獣", "#79cf69",\n      "Order signature: +15% ATK, +15% HP and +4 HP regeneration. Unlocks Twin-Beast Invocation.",\n      { special: true, atk: 1.15, hp: 1.15, regen: 4 },\n      { name: "Twin-Beast Invocation", power: 0.78, stat: "nin", hits: 2, note: "two natural-energy summons strike in succession" }),\n  },\n  storm_caller: {\n    id: "storm_caller", title: "Storm Caller", epithet: "of the Four Tempests", color: "#8bc8ff", scoutable: false,\n    blurb: "One of the Four Storm Callers. Lightning chakra is threaded through every movement until speed itself becomes a weapon.",\n    bonus: { nin: 7, spd: 8, tac: 4 }, pot: 5,\n    perk: mk("lg_stormcrown", "Storm Crown", "雷", "#8bc8ff",\n      "Order signature: +15% ATK, +12% crit and +25% chakra. Unlocks Heaven-Splitter Bolt.",\n      { special: true, atk: 1.15, crit: 0.12, cp: 1.25 },\n      { name: "Heaven-Splitter Bolt", power: 1.22, stat: "nin", hits: 1, note: "a concentrated lightning execution strike" }),\n  },\n  masked_assassin: {\n    id: "masked_assassin", title: "Masked Assassin", epithet: "of the Nine Faces", color: "#c9b2ff", scoutable: false,\n    blurb: "One of the Nine Masked Assassins. Each mask records a perfected method of entering, killing and vanishing unseen.",\n    bonus: { ste: 9, spd: 6, tac: 5 }, pot: 4,\n    perk: mk("lg_facelesskilling", "Faceless Killing", "面", "#c9b2ff",\n      "Order signature: always acts first, +18% dodge and +16% crit. Unlocks Ninth Mask Severance.",\n      { special: true, firstStrike: true, dodge: 0.18, crit: 0.16 },\n      { name: "Ninth Mask Severance", power: 1.08, stat: "ste", hits: 2, note: "two silent cuts before the target can react" }),\n  },\n  gate_master: {\n    id: "gate_master", title: "Gate Master", epithet: "of the Eight Inner Gates", color: "#ff805f", scoutable: false,\n    blurb: "One of the Eight Gate Masters. Their body is conditioned to survive chakra output that would tear ordinary shinobi apart.",\n    bonus: { tai: 10, spd: 8, med: 3 }, pot: 5,\n    perk: mk("lg_innergates", "Inner Gates Release", "門", "#ff805f",\n      "Order signature: +30% ATK and +15% crit; attacks hit with exceptional force. Unlocks Gate-Breaking Barrage.",\n      { special: true, atk: 1.3, crit: 0.15, critMult: 0.25 },\n      { name: "Gate-Breaking Barrage", power: 0.88, stat: "tai", hits: 3, note: "a three-hit burst powered by opened chakra gates" }),\n  },\n  seal_bearer: {\n    id: "seal_bearer", title: "Forbidden Seal Bearer", epithet: "of the Sixfold Script", color: "#f0b36a", scoutable: false,\n    blurb: "One of the Six Forbidden Seal Bearers. Living formulae are written into their chakra network and answer violence with binding force.",\n    bonus: { nin: 8, gen: 7, med: 4, tac: 5 }, pot: 5,\n    perk: mk("lg_sixfoldseal", "Sixfold Living Seal", "封", "#f0b36a",\n      "Order signature: +25% DEF, +30% chakra, +3 HP regeneration and 25% counter chance. Unlocks Sixfold Binding Array.",\n      { special: true, def: 1.25, cp: 1.3, regen: 3, counter: 0.25 },\n      { name: "Sixfold Binding Array", power: 1.05, stat: "gen", hits: 1, note: "a living barrier formula collapses around the target" }),\n  },\n'''
s=s.replace(anchor, anchor+orders,1)
s=s.replace('export const LEGEND_IDS = Object.keys(LEGENDS);', 'export const LEGEND_IDS = Object.keys(LEGENDS);\nexport const SCOUT_LEGEND_IDS = LEGEND_IDS.filter((id) => LEGENDS[id].scoutable !== false);',1)
write(p,s)

# types.ts
p='src/game/types.ts'; s=read(p)
s=s.replace('specialRewardKind?: "potential" | "trait" | "unlock" | "jutsu" | "gear";', 'specialRewardKind?: "potential" | "trait" | "unlock" | "jutsu" | "gear" | "recruit";',1)
write(p,s)

# special missions
p='src/game/specialMissionsV2.ts'; s=read(p)
s=s.replace('  | { kind: "gear"; gearId: string; name: string };', '  | { kind: "gear"; gearId: string; name: string }\n  | { kind: "recruit"; legendId: string; name: string; maxOwned: number; startingRank: "chunin" | "jonin" };',1)
insert='''  { id: "nine_faces_invitation", name: "The Faceless Invitation", grade: "B", desc: "A black lacquer mask appears at the gate with a route to a hidden assassination trial. The Nine Faces are watching for a worthy village.", warning: "RARE ORDER RECRUIT: success convinces one of the Nine Masked Assassins to join the village. The order will never exceed nine members and cannot appear in normal scouting.", focus: ["ste", "spd", "tac"], slots: 2, reward: { kind: "recruit", legendId: "masked_assassin", name: "Masked Assassin", maxOwned: 9, startingRank: "chunin" } },\n  { id: "five_beast_covenant", name: "The Five Beast Covenant", grade: "A", desc: "Tracks from five different summons converge on an old natural-energy shrine where the Beast Sages choose their allies.", warning: "RARE ORDER RECRUIT: success earns the trust of one of the Five Beast Sages. They arrive with Primal Covenant already mastered. Maximum five in the village.", focus: ["nin", "tai", "med", "tac"], slots: 3, reward: { kind: "recruit", legendId: "beast_sage", name: "Beast Sage", maxOwned: 5, startingRank: "chunin" } },\n  { id: "four_tempests_summons", name: "Summons of the Four Tempests", grade: "A", desc: "A lightning-written challenge calls the village to a mountain ridge where four storm masters test speed, nerve and chakra control.", warning: "RARE ORDER RECRUIT: success recruits one of the Four Storm Callers. They cannot be scouted normally and arrive with Storm Crown mastered. Maximum four.", focus: ["nin", "spd", "tac"], slots: 3, reward: { kind: "recruit", legendId: "storm_caller", name: "Storm Caller", maxOwned: 4, startingRank: "chunin" } },\n  { id: "eight_gates_trial", name: "Trial of the Eight Inner Gates", grade: "S", desc: "An underground dōjō offers a live combat trial against a master who refuses to teach anyone unwilling to break their own limits.", warning: "EXTREME RARE ORDER TRIAL: failure is likely to cause severe injuries. Success recruits one of the Eight Gate Masters as a Jōnin with Inner Gates Release already mastered. Maximum eight.", focus: ["tai", "spd", "med", "tac"], slots: 3, reward: { kind: "recruit", legendId: "gate_master", name: "Gate Master", maxOwned: 8, startingRank: "jonin" } },\n  { id: "sixfold_seal_covenant", name: "The Sixfold Seal Covenant", grade: "S", desc: "Six living seal tablets react to the village's chakra signature and open a forbidden negotiation with their human bearers.", warning: "FORBIDDEN RARE ORDER: a failed attempt may injure the whole cell. Success recruits one of the Six Forbidden Seal Bearers as a Jōnin with Sixfold Living Seal mastered. Maximum six.", focus: ["nin", "gen", "med", "tac"], slots: 4, reward: { kind: "recruit", legendId: "seal_bearer", name: "Forbidden Seal Bearer", maxOwned: 6, startingRank: "jonin" } },\n'''
needle='  { id: "nine_seal_treasury", name: "The Nine-Seal Treasury"'
pos=s.find(needle)
if pos<0: raise SystemExit('special mission insertion anchor missing')
s=s[:pos]+insert+s[pos:]
s=s.replace('  if (r.kind === "gear") return `UNIQUE GEAR: ${r.name}`;\n  return `VILLAGE UNLOCK: ${r.key}`;', '  if (r.kind === "gear") return `UNIQUE GEAR: ${r.name}`;\n  if (r.kind === "recruit") return `RARE RECRUIT: ${r.name} (${r.maxOwned} ORDER CAP)`;\n  return `VILLAGE UNLOCK: ${r.key}`;',1)
write(p,s)

# engine.ts
p='src/game/engine.ts'; s=read(p)
s=s.replace('import { LEGENDS, LEGEND_IDS, pendingPerks, perkById, perkFx, perkTree } from "./perks";', 'import { LEGENDS, SCOUT_LEGEND_IDS, pendingPerks, perkById, perkFx, perkTree } from "./perks";',1)
s=s.replace('  if (legendId === "swordsman") add("bladeborn");', '  if (legendId === "swordsman") add("bladeborn");\n  if (legendId === "beast_sage") { add("fieldSurvivor"); add("fearless"); }\n  if (legendId === "storm_caller") add("chakraConductor");\n  if (legendId === "masked_assassin") add("nightOperative");\n  if (legendId === "gate_master") add("relentless");\n  if (legendId === "seal_bearer") add("chakraAnchor");',1)
s=s.replace('const available = LEGEND_IDS.filter((id) => !owned.has(id));', 'const available = SCOUT_LEGEND_IDS.filter((id) => !owned.has(id));',1)
old='const eligible = SPECIAL_MISSIONS.filter((d) => s.day >= SPECIAL_UNLOCK_DAY[d.grade]).filter((d) => !d.requiredNature || s.ninjas.some((n) => n.nature === d.requiredNature || n.secondaryNature === d.requiredNature));'
new='const eligible = SPECIAL_MISSIONS.filter((d) => s.day >= SPECIAL_UNLOCK_DAY[d.grade]).filter((d) => !d.requiredNature || s.ninjas.some((n) => n.nature === d.requiredNature || n.secondaryNature === d.requiredNature)).filter((d) => d.reward.kind !== "recruit" || s.ninjas.filter((n) => n.legend === d.reward.legendId).length < d.reward.maxOwned);'
if old not in s: raise SystemExit('eligible anchor missing')
s=s.replace(old,new,1)
oldid='specialRewardId: reward.kind === "trait" ? reward.trait : reward.kind === "jutsu" ? reward.jutsuId : reward.kind === "unlock" ? reward.key : reward.kind === "gear" ? reward.gearId : undefined'
newid='specialRewardId: reward.kind === "trait" ? reward.trait : reward.kind === "jutsu" ? reward.jutsuId : reward.kind === "unlock" ? reward.key : reward.kind === "gear" ? reward.gearId : reward.kind === "recruit" ? reward.legendId : undefined'
if oldid not in s: raise SystemExit('reward id anchor missing')
s=s.replace(oldid,newid,1)
marker='function applySpecialReward(s: GameState, m: Mission, squad: Ninja[]): string | undefined {'
if marker not in s: raise SystemExit('apply special anchor missing')
helper='''function makeRareOrderRecruit(s: GameState, legendId: string, startingRank: "chunin" | "jonin"): Ninja {\n  const n = makeNinja(s, true, legendId);\n  n.rank = startingRank;\n  n.level = startingRank === "jonin" ? 11 : 7;\n  n.sp = startingRank === "jonin" ? 4 : 2;\n  const extra = startingRank === "jonin" ? 7 : 4;\n  for (const k of SKILLS) {\n    if (k === "doj" && !dojutsuAwakened(n)) continue;\n    n.s[k] += extra;\n    n.growth[k] *= 1.06;\n  }\n  const signature = LEGENDS[legendId]?.perk.id;\n  if (signature && !n.perks.includes(signature)) n.perks.push(signature);\n  return n;\n}\n\n'''
s=s.replace(marker,helper+marker,1)
branch='  if (def.reward.kind === "gear") { const inv = ensureEquipmentState(s).inventory; inv[def.reward.gearId] = (inv[def.reward.gearId] ?? 0) + 1; return `Unique gear acquired: ${def.reward.name}. It has been added to the Equipment inventory.`; }\n'
if branch not in s: raise SystemExit('gear branch missing')
recruit='''  if (def.reward.kind === "recruit") {\n    const count = s.ninjas.filter((n) => n.legend === def.reward.legendId).length;\n    if (count >= def.reward.maxOwned) return `${def.reward.name} order is already at its ${def.reward.maxOwned}-member limit.`;\n    const recruit = makeRareOrderRecruit(s, def.reward.legendId, def.reward.startingRank);\n    s.ninjas.push(recruit);\n    return `Rare recruit joined: ${recruit.name} — ${LEGENDS[def.reward.legendId].title} ${LEGENDS[def.reward.legendId].epithet}. Order strength ${count + 1}/${def.reward.maxOwned}.`;\n  }\n'''
s=s.replace(branch,branch+recruit,1)
write(p,s)

# mission reports
p='src/game/missionReports.ts'; s=read(p)
needle='  "The Nine-Seal Treasury": { open: "Each chamber in the treasury carried a different sealing rule and punished the wrong answer immediately.", win: "All nine rooms were opened in sequence and the Nine-Seal Talisman removed without collapsing the barrier complex.", fail: "The sixth seal reflected the breach attempt and injured the cell badly enough to force retreat." },\n'
if needle not in s: raise SystemExit('mission report anchor missing')
reports='''  "The Faceless Invitation": { open: "A black lacquer mask at the gate contained only a route, a moon phase and the instruction: arrive unseen.", win: "The cell completed the assassination course without revealing its approach; one of the Nine Faces removed their mask and accepted a village headband.", fail: "The final observer marked the cell before they reached the extraction point. The mask was gone when they returned to the gate." },\n  "The Five Beast Covenant": { open: "Five different animal tracks circled the natural-energy shrine without ever crossing one another.", win: "The shrine answered the cell's chakra and a Beast Sage stepped from the summon mist to swear a new covenant with the village.", fail: "The natural-energy pressure overwhelmed the approach and the unseen sages ended the trial before the cell reached the inner stones." },\n  "Summons of the Four Tempests": { open: "Lightning wrote four challenge seals across the ridge while thunder rolled beneath a cloudless sky.", win: "The cell endured the storm trial until one of the Four Tempests lowered their hand and agreed to carry the village crest.", fail: "A chained lightning field split the formation and forced the team down the mountain before the final seal could be reached." },\n  "Trial of the Eight Inner Gates": { open: "The underground dōjō doors closed behind the team as a Gate Master opened the first seal without warning.", win: "The challengers survived the full live-combat test. Impressed, a Gate Master joined the village as a Jōnin and opened their signature technique to the roster.", fail: "The trial ended only when the instructors intervened to prevent permanent damage; the team returned with serious injuries and no recruit." },\n  "The Sixfold Seal Covenant": { open: "Six living seal tablets rotated around the negotiation chamber and tested every chakra signature that entered.", win: "The final script accepted the village seal. One Forbidden Seal Bearer broke from the circle and joined the village as its newest Jōnin.", fail: "The fifth script rejected the cell and reflected its binding formula through the chamber, forcing an immediate retreat." },\n'''
s=s.replace(needle,reports+needle,1)
write(p,s)

# service worker cache bump but preserve validation substring
p='public/sw.js'; s=read(p)
s,n=re.subn(r'const CACHE = "[^"]+";', 'const CACHE = "shadow-village-depth-v1-jutsu-potential-v6-rare-orders";', s, count=1)
